16	
17	    public BaseRepository(ILogger<BaseRepository<TEntity>> logger, CmContext context)
18	    {
19	        _logger = logger;
20	        Context = context;
21	    }
22	
23	    public async Task<IEnumerable<TEntity>> GetAllAsync()
24	        => await Set.ToListAsync();
25	
26	    public async Task<IEnumerable<TEntity>> GetAsync(Expression<Func<TEntity, bool>> predicate)
27	        => await Set.Where(predicate).ToListAsync();
28	
29	    public async Task<TEntity?> GetAsync(int id)
30	    {
31	        var entity = await Set.FindAsync(id);
32	        return entity?.RecordStateId == (int)RecordStateTypeId.Active ? entity : null;
33	    }
34	
35	    public async Task<bool> UpdateAsync(TEntity entity)
36	    {
37	        Context.Entry(entity).State = EntityState.Modified;
38	        return await Context.SaveChangesAsync() > 0;
39	    }
40	
41	    public async Task<bool> AddAsync(TEntity entity)
42	    {
43	        await Set.AddAsync(entity);
44	        return await Context.SaveChangesAsync() > 0;
45	    }
46	
47	    public async Task<bool?> DeleteAsync(int id)
48	    {
49	        var entity = await Set.FindAsync(id);
50	        if (entity is null) return null;
51	        return await DeleteAsync(entity);
52	    }
53	
54	    public async Task<bool?> DeleteAsync(TEntity entity)
55	    {
56	        entity.RecordStateId = (int)RecordStateTypeId.Deleted;
57	        return await UpdateAsync(entity);
58	    }
59	}
