38	        {
39	            options.Password.RequireDigit = true;
40	            options.Password.RequiredLength = 8;
41	            options.Password.RequireNonAlphanumeric = true;
42	            options.Password.RequireUppercase = true;
43	            options.Lockout.MaxFailedAccessAttempts = 5;
44	            options.Lockout.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(15);
45	            options.User.RequireUniqueEmail = true;
46	        })
47	        .AddRoles<IdentityRole<int>>()
